package ai.xzkj.recruitment.browsercompanion;
import ai.xzkj.recruitment.auth.SystemUser;import ai.xzkj.recruitment.boss.BossAccount;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="browser_pairing_codes") public class BrowserPairingCode{
 @Id private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="boss_account_id")private BossAccount account;@Column(name="token_hash",nullable=false,length=64)private String tokenHash;@Column(name="expires_at",nullable=false)private Instant expiresAt;@Column(name="used_at")private Instant usedAt;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="created_by")private SystemUser createdBy;@Column(name="created_at",nullable=false)private Instant createdAt;protected BrowserPairingCode(){}public BrowserPairingCode(BossAccount a,String h,SystemUser u){id=UUID.randomUUID();account=a;tokenHash=h;createdBy=u;createdAt=Instant.now();expiresAt=createdAt.plusSeconds(600);}public boolean usable(Instant now){return usedAt==null&&expiresAt.isAfter(now);}public void use(){usedAt=Instant.now();}public BossAccount getAccount(){return account;}public SystemUser getCreatedBy(){return createdBy;}public Instant getExpiresAt(){return expiresAt;}
}
